CREATE TABLE IF NOT EXISTS audiences (id INTEGER PRIMARY KEY AUTOINCREMENT,app_id TEXT NOT NULL DEFAULT 'principal-ed',name TEXT NOT NULL,description TEXT,audience_type TEXT NOT NULL DEFAULT 'custom',status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','withdrawn')),created_by TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT(datetime('now')),updated_at TEXT NOT NULL DEFAULT(datetime('now')),UNIQUE(app_id,name));
CREATE TABLE IF NOT EXISTS audience_members (id INTEGER PRIMARY KEY AUTOINCREMENT,audience_id INTEGER NOT NULL,party_type TEXT NOT NULL CHECK(party_type IN ('user','staff','student','guardian','team','external')),party_id TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'member',status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','withdrawn')),added_by TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT(datetime('now')),UNIQUE(audience_id,party_type,party_id,role),FOREIGN KEY(audience_id) REFERENCES audiences(id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS idx_audiences_app ON audiences(app_id,status,updated_at);CREATE INDEX IF NOT EXISTS idx_audience_members ON audience_members(audience_id,status);
